from typing import List, Dict, Any
from collections import defaultdict
from datetime import datetime


def compute_total_revenue(transactions: List[Dict[str, Any]]) -> float:
    """Compute total revenue from a list of transactions.

    Each transaction is expected to be a dict containing at least:
      - 'price' (numeric or string)
      - 'quantity' (numeric or string, optional, default 1)

    Returns the total revenue as a float.
    """
    total = 0.0
    for t in transactions:
        try:
            price = float(t.get('price', 0))
        except (TypeError, ValueError):
            price = 0.0
        try:
            quantity = float(t.get('quantity', 1))
        except (TypeError, ValueError):
            quantity = 1.0
        total += price * quantity
    return total


def revenue_by_product(transactions: List[Dict[str, Any]]) -> Dict[str, float]:
    """Return a mapping product_id -> revenue.

    If a transaction doesn't include 'product_id', it will be grouped under 'unknown'.
    """
    rev = defaultdict(float)
    for t in transactions:
        pid = t.get('product_id') or t.get('product') or 'unknown'
        try:
            price = float(t.get('price', 0))
        except (TypeError, ValueError):
            price = 0.0
        try:
            quantity = float(t.get('quantity', 1))
        except (TypeError, ValueError):
            quantity = 1.0
        rev[str(pid)] += price * quantity
    return dict(rev)


def revenue_by_month(transactions: List[Dict[str, Any]]) -> Dict[str, float]:
    """Return revenue grouped by month in 'YYYY-MM' format.

    Each transaction should include a 'date' field as an ISO-like string (e.g. '2023-07-15').
    Transactions with unparsable or missing dates are grouped under 'unknown'.
    """
    rev = defaultdict(float)

    def parse_month(date_val: Any) -> str:
        if not date_val:
            return 'unknown'
        if isinstance(date_val, datetime):
            return date_val.strftime('%Y-%m')
        s = str(date_val)
        # Try a few common ISO formats
        for fmt in ('%Y-%m-%d', '%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S', '%Y-%m'):
            try:
                dt = datetime.strptime(s, fmt)
                return dt.strftime('%Y-%m')
            except Exception:
                continue
        # last resort: try fromisoformat (covers offsets)
        try:
            dt = datetime.fromisoformat(s)
            return dt.strftime('%Y-%m')
        except Exception:
            return 'unknown'

    for t in transactions:
        month = parse_month(t.get('date'))
        try:
            price = float(t.get('price', 0))
        except (TypeError, ValueError):
            price = 0.0
        try:
            quantity = float(t.get('quantity', 1))
        except (TypeError, ValueError):
            quantity = 1.0
        rev[month] += price * quantity
    return dict(rev)


