def compute_revenue(prices, quantities):
    """Compute revenue per item and total revenue.

    Args:
        prices (list of numbers): Unit prices for items.
        quantities (list of numbers): Quantities sold for corresponding items.

    Returns:
        dict: {"per_item": [price*quantity,...], "total": sum_of_revenues}

    Raises:
        ValueError: if lengths mismatch or inputs cannot be converted to floats.
    """
    if not isinstance(prices, (list, tuple)) or not isinstance(quantities, (list, tuple)):
        raise ValueError("prices and quantities must be lists or tuples")
    if len(prices) != len(quantities):
        raise ValueError("prices and quantities must have the same length")
    revenues = []
    for p, q in zip(prices, quantities):
        try:
            rp = float(p)
            rq = float(q)
        except Exception as e:
            raise ValueError("price and quantity must be numeric") from e
        revenues.append(rp * rq)
    total = sum(revenues)
    return {"per_item": revenues, "total": total}


