def compute_total_revenue(transactions):
    """
    Calculate total revenue from an iterable of transactions.

    Accepted transaction formats:
      - dict with keys 'price' and 'quantity'
      - 2-element sequence or tuple: (price, quantity)

    Returns a float: sum(price * quantity) for all transactions.
    """
    total = 0.0
    for t in transactions:
        if isinstance(t, dict):
            price = t.get('price', 0)
            qty = t.get('quantity', 0)
        else:
            try:
                price, qty = t
            except Exception:
                raise ValueError("Each transaction must be a dict with 'price' and 'quantity' or a 2-element sequence")
        try:
            price = float(price)
            qty = float(qty)
        except Exception:
            raise ValueError("Price and quantity must be numeric")
        total += price * qty
    return total


